function s(v) { return String(v == null ? '' : v).trim(); }
function nz(x) { return s(x).toLowerCase().replace(/[^a-z0-9]/g, ''); }
const vr = $('GET sheets').first().json.valueRanges || [];
const st = (vr[0] || {}).values || [];
const tpl = (vr[1] || {}).values || [];
if (st.length < 40 || tpl.length < 2) { throw new Error('ABORT: short read'); }

const HIDE_RAISE = {};
['Body & Beyond','MonitorExam','Outlanders','ServeAmigo','SkillBytes','Fire Armor','Vira Jal','Washtro','Fuski.AI','Koncite','Pixelence','Tronix.AI','Vilva AI','Formverse','Opulytics','Train Rex','Orbit AI','Xproguard','Indie Stori','Springbase.ai','Appli','Luxova','AI Signal Labs','Desi Machines','Doffair','bezgoFresh','Chayan Karo'].forEach(function (n) { HIDE_RAISE[nz(n)] = 1; });
// A raise word followed by ANY digit within 40 chars. Currency-token matching failed on "5Cr"
// (no word boundary between digit and unit), so a digit is the reliable signal.
// "the fundraising round" in the template body has no digit after it, so it is not caught.
const BAD = /(?:rais(?:e|ed|es|ing)|fund\s*ask|funding\s*ask|fund\s*raise)[^.<]{0,40}?\d|pre-?\s*revenue|pre-?\s*launch|pre-?\s*monetis|pre-?\s*monetiz/i;
function cleanSegments(txt) { return s(txt).split('|').map(function (x) { return x.trim(); }).filter(function (x) { return x && !BAD.test(x); }).join(' | '); }
function stripTags(h) { return s(h).replace(/<[^>]*>/g, ' ').replace(/&nbsp;/g, ' ').replace(/&amp;/g, '&').replace(/&mdash;/g, '-').replace(/&ndash;/g, '-').replace(/&rsquo;/g, "'").replace(/\s+/g, ' ').trim(); }
function sanitiseMemo(html) {
  const blocks = s(html).split(/(?<=<\/(?:p|div|li|h[1-6]|ul|ol)>)/);
  const out = []; const dropped = [], edited = [];
  for (const b of blocks) { const text = stripTags(b);
    if (!text) { out.push(b); continue; }
    if (!BAD.test(text)) { out.push(b); continue; }
    const cleaned = cleanSegments(text);
    if (cleaned && cleaned.length >= 25 && !BAD.test(cleaned)) {
      out.push('<div style="font-family:Arial,Helvetica,sans-serif;font-size:14px;line-height:1.65;color:#222222;margin:0 0 12px 0;">' + cleaned + '</div>');
      edited.push({ was: text.slice(0, 160), now: cleaned.slice(0, 160) }); }
    else { dropped.push(text.slice(0, 160)); } }
  return { html: out.join(''), dropped: dropped, edited: edited }; }

const sh = (st[0] || []).map(s);
const S = {}; ['startup','sector','stage','raise_inr_cr','memo_html','highlight_1','highlight_2','highlight_3','active'].forEach(function (n) { S[n] = sh.indexOf(n); });
const th = (tpl[0] || []).map(s);
const T = {}; ['template_id','subject','body'].forEach(function (n) { T[n] = th.indexOf(n); });
let subjTpl = '';
for (let r = 1; r < tpl.length; r++) { if (s((tpl[r] || [])[T.template_id]) === 'INITIAL') { subjTpl = s((tpl[r] || [])[T.subject]); } }
if (!subjTpl) { throw new Error('ABORT: INITIAL subject template not found'); }

const SHOW = {}; ['ServeAmigo','Vira Jal','Fire Armor','SkillBytes','Train Rex'].forEach(function (n) { SHOW[nz(n)] = 1; });
const out = []; let checkedAll = 0, fellBack = 0;
for (let r = 1; r < st.length; r++) { const row = st[r] || []; const n = s(row[S.startup]); if (!n) { continue; }
  if (s(row[S.active]).toLowerCase() !== 'yes') { continue; }
  if (!HIDE_RAISE[nz(n)]) { continue; }
  checkedAll++;
  let subj = subjTpl.split('{{StartupName}}').join(n).split('{{Sector}}').join(s(row[S.sector])).split('{{FundraiseAmount}}').join(s(row[S.raise_inr_cr]));
  const subjBefore = subj;
  subj = subj.replace(/\s*\|\s*Rais(?:e|es|ing)\b[^|]*$/i, '').trim();
  if (BAD.test(subj)) { subj = n + ' - ' + cleanSegments(s(row[S.sector])); }
  const res = sanitiseMemo(row[S.memo_html]);
  let memo = res.html; let usedFallback = false;
  if (BAD.test(stripTags(memo))) { usedFallback = true; fellBack++;
    const hs = [s(row[S.highlight_1]), s(row[S.highlight_2]), s(row[S.highlight_3])].filter(function (x) { return x && !BAD.test(x); });
    memo = '<div style="font-family:Arial,Helvetica,sans-serif;font-size:14px;line-height:1.65;color:#222222;">'
      + '<div style="font-weight:700;color:#000000;margin:0 0 6px 0;">' + n + '</div>'
      + '<div style="margin:0 0 12px 0;">' + cleanSegments(s(row[S.sector])) + '</div>'
      + '<ul style="margin:0 0 14px 0;padding-left:20px;">' + hs.map(function (h) { return '<li style="margin:0 0 6px 0;">' + h + '</li>'; }).join('') + '</ul></div>'; }
  const leak = BAD.test(stripTags(memo)) || BAD.test(subj);
  const rec = { startup: n, raise_hidden: s(row[S.raise_inr_cr]), subject_after: subj,
    blocks_edited: res.edited.length, blocks_dropped: res.dropped.length, used_fallback: usedFallback, LEAK: leak,
    memo_len_before: s(row[S.memo_html]).length, memo_len_after: memo.length };
  if (SHOW[nz(n)]) { rec.edited_samples = res.edited.slice(0, 4); rec.dropped_samples = res.dropped.slice(0, 5); rec.memo_text_after = stripTags(memo).slice(0, 700); }
  out.push(rec); }
const leaks = out.filter(function (x) { return x.LEAK; });
// belt and braces: scan every produced memo for a raise word near a digit one more time
return [{ json: { startups_checked: checkedAll, used_fallback: fellBack, leaks_remaining: leaks.length,
  leaking: leaks.map(function (x) { return x.startup; }), results: out } }];
